// One-off importer: builds src/data/exercises.json from the public-domain
// free-exercise-db dataset (https://github.com/yuhonas/free-exercise-db, Unlicense)
// and downloads the start/end photos into public/ex/.
//
// Usage: node scripts/import-exercises.mjs <path-to-exercises.json> [--no-images]
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const IMG_BASE = 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/';

// Curated list of common gym machines & cable stations.
// `src` = dataset id (for instructions/muscles/images). `look` = how to recognise the machine.
// `pattern` = the movement it trains, for the routine check: h-push, v-push, h-pull, v-pull, squat,
// hinge, lunge, core or carry. Flies and rear-delt work count with their plane; curls, triceps work,
// raises, shrugs and calf work have no pattern.
// `primary` / `secondary` = the muscles it trains, overriding the dataset's. The app splits shoulders into
// Front, Side and Rear Delts, and only credits muscles that do real work: squats and leg presses don't
// count for hamstrings or calves, and a deadlift is mainly glutes, hamstrings and lower back.
// `edits` = [find, replace] fixes to the dataset's instructions (a string or a regex). Each must match.
// The dataset's "(Note: ... foot positioning section)" refers to a page that isn't part of the app.
const STANCE_NOTE = [/ ?\(Note: For the purposes of this discussion[^)]*\)\.?/, ''];

