const datasetPath = process.argv[2];
if (!datasetPath) { console.error('Usage: node scripts/import-exercises.mjs <exercises.json> [--no-images]'); process.exit(1); }
const noImages = process.argv.includes('--no-images');
const dataset = JSON.parse(await fs.readFile(datasetPath, 'utf8'));
const byId = new Map(dataset.map((e) => [e.id, e]));

const cap = (s) => s.replace(/\b\w/g, (c) => c.toUpperCase());
// Applies [find, replace] fixes to an exercise's instructions. A fix that matches nothing fails the import.
function edited(steps, edits, id) {
  let out = steps;
  for (const [find, to] of edits) {
    const hits = (t) => (typeof find === 'string' ? t.includes(find) : find.test(t));
    if (!out.some(hits)) throw new Error(`${id}: edit matches nothing: ${find}`);
    out = out.map((t) => (hits(t) ? t.replace(find, to) : t));
  }
  return out.map((t) => t.replace(/\s{2,}/g, ' ').trim()).filter(Boolean);
}
const out = [];
for (const c of CURATED) {
  // `src: null` is an exercise written here in full, with its own id, muscles and instructions, and no photos.
  const src = c.src === null ? { images: [], primaryMuscles: [], secondaryMuscles: [], instructions: [] } : byId.get(c.src);
  if (!src) throw new Error(`Missing dataset id ${c.src}`);
  if (c.src === null && !(c.id && c.primary && c.secondary && c.instructions)) throw new Error(`${c.name}: an exercise without src needs id, primary, secondary and instructions`);
  const id = c.id ?? c.src;
  const images = [];
  // A hand-written exercise can have photos of its own: `photos: n` expects public/ex/<id>/0.jpg … n-1.jpg.
  for (let i = 0; i < (c.photos ?? 0); i++) {
    const rel = `ex/${id}/${i}.jpg`;
    try { await fs.access(path.join(ROOT, 'public', rel)); } catch { throw new Error(`${id}: photo ${rel} is missing`); }
    images.push(rel);
  }
  for (let i = 0; i < src.images.length && i < 2; i++) {
    const rel = `ex/${id}/${i}.jpg`;
    images.push(rel);
    if (noImages) continue;
    const dest = path.join(ROOT, 'public', rel);
    try { await fs.access(dest); continue; } catch { /* download */ }
    const res = await fetch(IMG_BASE + src.images[i]);
    if (!res.ok) throw new Error(`Image ${src.images[i]}: HTTP ${res.status}`);
    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.writeFile(dest, Buffer.from(await res.arrayBuffer()));
  }
  out.push({
    id,
    name: c.name,
    aliases: c.aliases ?? [],
    group: c.group,
    equipment: c.equipment,
    primaryMuscles: c.primary ?? src.primaryMuscles.map(cap),
    secondaryMuscles: c.secondary ?? src.secondaryMuscles.map(cap),
    look: c.look,
    instructions: edited(c.instructions ?? src.instructions, c.edits ?? [], id),
    images,
    ...(c.assisted ? { assisted: true } : {}),
    ...(c.bwFactor ? { bwFactor: c.bwFactor } : {}),
    ...(c.loadFactor ? { loadFactor: c.loadFactor } : {}),
    ...(c.barKg ? { barKg: c.barKg } : {}),
    ...(c.benchmark ? { benchmark: c.benchmark } : {}),
    ...(c.vestMult ? { vestMult: c.vestMult } : {}),
    ...(c.hold ? { hold: true } : {}),
    ...(c.pattern ? { pattern: c.pattern } : {}),
  });
}
await fs.writeFile(path.join(ROOT, 'src/data/exercises.json'), JSON.stringify(out, null, 1) + '\n');
console.log(`Wrote ${out.length} exercises`);
